sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var pan = current.getValue('pan');
    if (!pan) return;

    var PERF_TABLE = 'x_birl3_clm_customer_performance';
    var CUST_TABLE = 'x_birl3_clm_clm_customer_master1';
    var REUSE_HOURS = 24;
    var STALE_MINUTES = 10;

    // 1. Check if a performance record already exists for this PAN
    var pGr = new GlideRecord(PERF_TABLE);
    pGr.addQuery('customer_name.pan', pan);
    pGr.orderByDesc('sys_updated_on');
    pGr.setLimit(1);
    pGr.query();

    var exists = pGr.next();
    if (exists) {
        var updatedGDT = new GlideDateTime(pGr.getValue('sys_updated_on'));
        var nowGDT = new GlideDateTime();
        var diffHours = (nowGDT.getNumericValue() - updatedGDT.getNumericValue()) / 3600000;
        var isCurrentDay = (updatedGDT.getLocalDate().getValue() === nowGDT.getLocalDate().getValue());
        var status = pGr.getValue('assessment_status');

        // DO NOT re-trigger if already assessed today, within 24 hours, or currently running
        if ((status === 'completed' && (isCurrentDay || diffHours < REUSE_HOURS)) || 
            (status === 'requested' && (diffHours * 60) < STALE_MINUTES)) {
            return;
        }
    }

    // 2. Resolve Customer Master sys_id for the reference field 'customer_name'
    var custSysId = '';
    var compName = current.getValue('company_name') || '';

    var cmGr = new GlideRecord(CUST_TABLE);
    cmGr.addQuery('pan', pan);
    cmGr.setLimit(1);
    cmGr.query();
    if (cmGr.next()) {
        custSysId = cmGr.getUniqueValue();
        if (!compName) {
            compName = cmGr.getValue('customer_name') || cmGr.getValue('name') || '';
        }
    }

    // 3. Update existing record if older than 24h, or insert a single new row
    var targetGr = exists ? pGr : new GlideRecord(PERF_TABLE);
    if (!exists) {
        targetGr.initialize();
        if (custSysId) {
            targetGr.setValue('customer_name', custSysId); // Sets reference to customer master
        }
    }

    targetGr.setValue('company_name', compName);
    targetGr.setValue('current_stock_price', '');
    targetGr.setValue('market_stock_insight', '');
    targetGr.setValue('financial_highlights', '');
    targetGr.setValue('major_developments', '');
    targetGr.setValue('key_news_highlights', '');
    targetGr.setValue('final_recommendation', '');
    targetGr.setValue('requested_by', gs.getUserID());
    targetGr.setValue('assessment_status', 'requested');

    if (exists) {
        targetGr.update();
    } else {
        targetGr.insert();
    }

})(current, previous);
